  function getAutoCardAPI(){
    try{if(parent&&parent.AutoCardUpdaterAPI)return parent.AutoCardUpdaterAPI;}catch(e){}
    if(window.AutoCardUpdaterAPI)return window.AutoCardUpdaterAPI;
    return null;
  }

  function getSheetByName(tableName) {
    const API = getAutoCardAPI();
    const all = API ? API.exportTableAsJson() : {};
    for (const key in all) {
      if (!key.startsWith('sheet_')) continue;
      if (all[key].name === tableName) return all[key];
    }
    for (const key in all) {
      if (!key.startsWith('sheet_')) continue;
      const ddl = all[key].sourceData?.ddl || '';
      const m = ddl.match(/CREATE\s+TABLE\s+(?:IF\s+NOT\s+EXISTS\s+)?(\w+)/i);
      if (m && m[1] === tableName) return all[key];
    }
    return null;
  }

  function getCellByHeader(tableName, rowIndex, colName) {
    const sheet = getSheetByName(tableName);
    if (!sheet) return null;
    const headers = sheet.content[0];
    const colIdx = headers.indexOf(colName);
    if (colIdx === -1) return null;
    return sheet.content[rowIndex]?.[colIdx] ?? null;
  }

  function findRowByColumn(tableName, colName, value) {
    const sheet = getSheetByName(tableName);
    if (!sheet) return -1;
    const headers = sheet.content[0];
    const colIdx = headers.indexOf(colName);
    if (colIdx === -1) return -1;
    for (let i = 1; i < sheet.content.length; i++) {
      if (String(sheet.content[i][colIdx]) === String(value)) return i;
    }
    return -1;
  }

  function getInitials(name){ return name ? name.charAt(0) : '?'; }
  function resolveAvatar(name){
    if(_avatarCache[name] !== undefined) return _avatarCache[name];
    try{
      var api = (typeof window!=='undefined'&&window.top&&window.top.BubbleAvatar) ? window.top.BubbleAvatar : null;
      if(api && api.getAvatar){
        api.getAvatar(name).then(function(url){
          _avatarCache[name] = url || null;
          if(url) updateAvatarImages(name, url);
        }).catch(function(){ _avatarCache[name] = null; });
        _avatarCache[name] = null;
        return null;
      }
    }catch(e){}
    _avatarCache[name] = null;
    return null;
  }
  function updateAvatarImages(name, url){
    document.querySelectorAll('[data-avatar-name="'+name+'"] img').forEach(function(img){ img.src = url; });
    document.querySelectorAll('[data-avatar-name="'+name+'"]').forEach(function(el){
      var initials = el.querySelector('.initials,.ti');
      if(initials && url){
        var existing = el.querySelector('img');
        if(!existing){
          var img = document.createElement('img');
          img.src = url;
          img.alt = name;
          initials.style.display = 'none';
          el.insertBefore(img, initials);
        }
      }
    });
  }

