    p.style.cssText = 'left:' + x + 'px;top:' + y + 'px;width:' + size + 'px;height:' + size + 'px;background:hsl(' + h.toFixed(0) + ',80%,72%);box-shadow:0 0 ' + (size * 2) + 'px hsl(' + h.toFixed(0) + ',80%,65%)';
    wrap.appendChild(p);
    p.animate([
      {opacity: 0, transform: 'scale(0)'},
      {opacity: 0.9, transform: 'scale(1.3)', offset: 0.15},
      {opacity: 0.5, transform: 'scale(0.7)', offset: 0.6},
      {opacity: 0, transform: 'scale(0) translate(' + ((ex - x)) + 'px,' + ((ey - y)) + 'px)'}
    ], {duration: 700 + Math.random() * 500, easing: 'ease-out'});
    setTimeout(function(){p.remove();}, 1300);
  }

