  function _buildRing(pct, segs) {
    segs = segs || 36;
    var cx = 32, cy = 32, r = 28;
    var arcSpan = 270;
    var startA = 135;
    var endA = startA + arcSpan * pct;
    var swMin = 2, swMax = 6.5;
    var hStart = 340, hEnd = 268, sStart = 80, sEnd = 80, lStart = 75, lEnd = 55;
    var paths = '';
    var bgEnd = startA + arcSpan;
    var bgx0 = cx + r * Math.cos(startA * Math.PI / 180);
    var bgy0 = cy + r * Math.sin(startA * Math.PI / 180);
    var bgx1 = cx + r * Math.cos(bgEnd * Math.PI / 180);
    var bgy1 = cy + r * Math.sin(bgEnd * Math.PI / 180);
    var bgLa = arcSpan > 180 ? 1 : 0;
    var bg = '<path d="M' + bgx0.toFixed(2) + ' ' + bgy0.toFixed(2) + ' A' + r + ' ' + r + ' 0 ' + bgLa + ' 1 ' + bgx1.toFixed(2) + ' ' + bgy1.toFixed(2) + '" stroke="rgba(200,180,210,0.12)" stroke-width="2.5" fill="none" stroke-linecap="round"/>';
    for (var i = 0; i < segs; i++) {
      var t0 = i / segs, t1 = (i + 1) / segs;
      var a0 = startA + (endA - startA) * t0;
      var a1 = startA + (endA - startA) * t1;
      var tFill = (t0 + t1) / 2;
      var tColorNorm = ((a0 + a1) / 2 - startA) / arcSpan;
      var sw = swMin + (swMax - swMin) * Math.pow(tFill, 0.6);
      var h = hStart + (hEnd - hStart) * tColorNorm;
      var s = sStart + (sEnd - sStart) * tColorNorm;
      var l = lStart + (lEnd - lStart) * tColorNorm;
      var color = 'hsl(' + h.toFixed(1) + ',' + s.toFixed(0) + '%,' + l.toFixed(0) + '%)';
      var glow = 'hsla(' + h.toFixed(1) + ',' + s.toFixed(0) + '%,' + l.toFixed(0) + '%,0.6)';
      var x0 = cx + r * Math.cos(a0 * Math.PI / 180);
      var y0 = cy + r * Math.sin(a0 * Math.PI / 180);
      var x1 = cx + r * Math.cos(a1 * Math.PI / 180);
      var y1 = cy + r * Math.sin(a1 * Math.PI / 180);
      var la = (a1 - a0) > 180 ? 1 : 0;
      paths += '<path d="M' + x0.toFixed(2) + ' ' + y0.toFixed(2) + ' A' + r + ' ' + r + ' 0 ' + la + ' 1 ' + x1.toFixed(2) + ' ' + y1.toFixed(2) + '" stroke="' + color + '" stroke-width="' + sw.toFixed(1) + '" fill="none" stroke-linecap="round" style="filter:drop-shadow(0 0 ' + (sw * 0.6).toFixed(1) + 'px ' + glow + ')"/>';
    }
    return bg + paths;
  }

  function _spawnRingParticle(wrap, pct) {
    var p = document.createElement('div');
    p.className = 'ring-particle';
    var startA = 135;
    var angle = startA + Math.random() * 270 * pct;
    var r = 30;
    var cx = 32, cy = 32;
    var rad = angle * Math.PI / 180;
    var x = cx + r * Math.cos(rad);
    var y = cy + r * Math.sin(rad);
    var t = (angle - startA) / (270 * pct);
    var h = 340 + (268 - 340) * t;
    var size = 1.5 + Math.random() * 2.5;
    var driftR = 3 + Math.random() * 6;
    var ex = cx + (r + driftR) * Math.cos(rad);
    var ey = cy + (r + driftR) * Math.sin(rad);
    p.style.cssText = 'left:' + x + 'px;top:' + y + 'px;width:' + size + 'px;height:' + size + 'px;background:hsl(' + h.toFixed(0) + ',80%,72%);box-shadow:0 0 ' + (size * 2) + 'px hsl(' + h.toFixed(0) + ',80%,65%)';
    wrap.appendChild(p);
    p.animate([
      {opacity: 0, transform: 'scale(0)'},
      {opacity: 0.9, transform: 'scale(1.3)', offset: 0.15},
      {opacity: 0.5, transform: 'scale(0.7)', offset: 0.6},
      {opacity: 0, transform: 'scale(0) translate(' + ((ex - x)) + 'px,' + ((ey - y)) + 'px)'}
    ], {duration: 700 + Math.random() * 500, easing: 'ease-out'});
    setTimeout(function(){p.remove();}, 1300);
  }

