  var _ringRunners = [];
  function _initRingRunners() {
    document.querySelectorAll('.char-avatar-wrap[data-tv]').forEach(function(wrap) {
      var tv = parseInt(wrap.dataset.tv) || 0;
      if(tv === 0) return;
      var pct = tv / 1000;
      var trailCount = 4;
      var els = [];
      var head = document.createElement('div');
      head.className = 'ring-runner';
      wrap.appendChild(head);
      els.push(head);
      for(var t = 0; t < trailCount; t++){
        var trail = document.createElement('div');
        trail.className = 'ring-trail';
        wrap.appendChild(trail);
        els.push(trail);
      }
      _ringRunners.push({wrap:wrap, pct:pct, els:els, progress:0, speed:0.004 + pct * 0.003});
    });
    function tick() {
      var cx = 32, cy = 32, r = 28, startA = 135;
      _ringRunners.forEach(function(run){
        run.progress += run.speed;
        if(run.progress > 1) run.progress -= 1;
        var angle = startA + 270 * run.pct * run.progress;
        var rad = angle * Math.PI / 180;
        var x = cx + r * Math.cos(rad);
        var y = cy + r * Math.sin(rad);
        var colorT = (angle - startA) / 270;
        var h = 340 + (268 - 340) * colorT;
        var sw = 2 + 4.5 * Math.pow(run.progress, 0.6);
        var headEl = run.els[0];
        var sz = 5 + sw;
        headEl.style.cssText = 'width:'+sz+'px;height:'+sz+'px;left:'+(x-sz/2)+'px;top:'+(y-sz/2)+'px;opacity:0.95;background:radial-gradient(circle,hsla('+h.toFixed(0)+',90%,82%,1) 0%,hsla('+h.toFixed(0)+',85%,65%,0.5) 35%,transparent 70%);box-shadow:0 0 '+(sw*1.2)+'px hsla('+h.toFixed(0)+',85%,68%,0.7),0 0 '+(sw*3)+'px hsla('+h.toFixed(0)+',80%,60%,0.25)';
        for(var i = 1; i < run.els.length; i++){
          var tp = run.progress - i * 0.025;
          if(tp < 0) tp += 1;
          var ta = startA + 270 * run.pct * tp;
          var tr = ta * Math.PI / 180;
          var tx = cx + r * Math.cos(tr);
          var ty = cy + r * Math.sin(tr);
          var tColorT = (ta - startA) / 270;
          var th = 340 + (268 - 340) * tColorT;
          var tOp = 0.5 - i * 0.12;
          var tSz = (5 + sw) * (1 - i * 0.15);
          run.els[i].style.cssText = 'width:'+tSz+'px;height:'+tSz+'px;left:'+(tx-tSz/2)+'px;top:'+(ty-tSz/2)+'px;opacity:'+tOp.toFixed(2)+';background:radial-gradient(circle,hsla('+th.toFixed(0)+',85%,75%,'+tOp.toFixed(2)+') 0%,transparent 65%)';
        }
        if(Math.random() < 0.35) _spawnRingParticle(run.wrap, run.pct);
      });
      requestAnimationFrame(tick);
    }
    requestAnimationFrame(tick);
  }

