<script>
(function(){
const openingEl = document.getElementById('openingContent');
const OPENING = openingEl ? openingEl.textContent.trim() : '';
const isQuick = OPENING.length > 0;
const customForm = document.getElementById('customForm');
const button = document.getElementById('startButton');

if (isQuick) {
  customForm.style.display = 'none';

  openingEl.classList.add('visible');
  button.textContent = '快速开始';
  document.getElementById('sysInfo').innerHTML = '<div class="sys-info-title">欢迎来到欲望风俗店 <span class="mode-tag quick">手枪卡模式</span></div>' +
    '<div class="mode-intro quick-intro"><strong>什么是手枪卡模式？</strong><br>跳过所有养成流程，开局全员调教值拉满（1000），所有角色已入店。你可以直接体验欲望风俗店的全部玩法，无需等待。</div>' +
    '<div class="mode-intro"><strong>想玩养成？切换到调教模式</strong><br>在 SillyTavern 中切换到开场白一即可进入调教模式——从零开始与角色相处、养成、调教，逐步解锁入店资格与玩法。</div><br>' +
    '<strong>有哪些玩法？</strong>状态栏的"玩法"下拉列出了所有可用玩法，随时切换。点击角色头像可查看完整身体档案。如果当前剧情中的玩法和下拉选项对不上，可以手动选择一下让系统同步。<br><br>' +
    '<strong>怎么开始？</strong><strong style="color:var(--accent)">必须点击下方的「快速开始」按钮</strong>来启动游戏——不要直接在酒馆输入框发消息。';
} else {
  customForm.style.display = '';
  openingEl.classList.remove('visible');
  button.textContent = '发送并生成开场白';
}

function readWorldBookEntry(key) {
    try {
        const roots = [window, window.parent, window.parent?.parent, window.top].filter(Boolean);
        for (const root of roots) {
            try {
                if (root.SillyTavern && typeof root.SillyTavern.getContext === 'function') {
                    const ctx = root.SillyTavern.getContext();
                    if (ctx && ctx.characters && ctx.characterId != null) {
                        const char = ctx.characters[ctx.characterId];
                        if (char?.data?.character_book?.entries) {
                            const entries = char.data.character_book.entries;
                            const entry = entries.find(e => {
                                const keys = e.keys || (e.key ? [e.key] : []);
                                return Array.isArray(keys) && keys.includes(key);
                            });
                            if (entry?.content) return entry.content;
                        }
                    }
                }
            } catch (_) {}
        }
    } catch (_) {}
    return null;
}

function sendToTavern(message) {
    try {
        if (parent.document.getElementById('send_textarea')) {
            const textarea = parent.document.getElementById('send_textarea');
            const sendButton = parent.document.getElementById('send_but');
            if (textarea && sendButton) {
                textarea.value = message;
                sendButton.click();
            }
        }
    } catch (e) {
        console.error('[欲望风俗店初始化] 发送消息失败:', e);
    }
}

function buildPrompt() {
    const gameMode = '调教模式';
    const char1 = document.getElementById('char1').value;
    const char2 = document.getElementById('char2').value;
    const outline = document.getElementById('outline').value.trim();

    if (!char1 && !char2) return null;

    const chars = [char1, char2].filter(Boolean);
    let prompt = '【当前模式：' + gameMode + '】请基于世界书中以下角色的设定与她们"与user的关系"字段，生成一段现实世界中的开场白：' + chars.join('、');
    prompt += '。';
    if (outline) {
        prompt += '场景大纲：' + outline + '。';
    }
    return prompt;
}

function initDatabase() {
    const templateBase64 = readWorldBookEntry('__ACU_TEMPLATE_DATA__');
    if (!templateBase64) return Promise.resolve(null);
    try {
        const binaryStr = atob(templateBase64);
        const bytes = new Uint8Array(binaryStr.length);
        for (let i = 0; i < binaryStr.length; i++) bytes[i] = binaryStr.charCodeAt(i);
        const templateData = JSON.parse(new TextDecoder('utf-8').decode(bytes));
        const runtimeRoot = (window.parent && window.parent !== window) ? window.parent : window;
        if (runtimeRoot.AutoCardUpdaterAPI && runtimeRoot.AutoCardUpdaterAPI.initGameSession) {
            return runtimeRoot.AutoCardUpdaterAPI.initGameSession({}, {
                injectTemplate: true,
                loadPreset: false,
                templateData: templateData
            });
        }
    } catch (e) {
        console.error('[欲望风俗店初始化] 表格模板解码失败:', e);
    }
    return Promise.resolve(null);
}

button.addEventListener('click', async function() {
    button.disabled = true;
    button.textContent = '初始化中...';
    const statusMsg = document.getElementById('statusMessage');

    try {
        const initResult = await initDatabase();
        if (initResult && !initResult.success) {
            console.error('[欲望风俗店初始化] 数据注入失败:', initResult.message);
            button.textContent = isQuick ? '快速开始' : '发送并生成开场白';
            button.disabled = false;
            return;
        }

        if (isQuick) {
            var quickMsg = '【当前模式：手枪卡模式】快速开始模式：所有角色已入店，调教值设为1000。第一轮回复要求：仅由星野凛在大厅做简短的迎接，询问{{user}}今天想体验什么。禁止引入其他角色，禁止推进剧情，禁止自行开展玩法。等待{{user}}的下一次输入。';
            sendToTavern(quickMsg);
            statusMsg.textContent = '全员满级，已进入风俗店';
            statusMsg.classList.add('show');
            button.textContent = '已进入';
        } else {
            const prompt = buildPrompt();
            if (!prompt) {
                statusMsg.textContent = '请至少选择一个角色';
                statusMsg.classList.add('show');
                setTimeout(function() { statusMsg.classList.remove('show'); }, 2000);
                button.textContent = '发送并生成开场白';
                button.disabled = false;
                return;
            }
            sendToTavern(prompt);
            statusMsg.textContent = '已发送，等待AI生成开场';
            statusMsg.classList.add('show');
            button.textContent = '已发送';
        }
        setTimeout(function() { statusMsg.classList.remove('show'); }, 3000);
    } catch (e) {
        console.error('[欲望风俗店初始化] 初始化失败:', e);
        button.textContent = isQuick ? '快速开始' : '发送并生成开场白';
        button.disabled = false;
    }
});
})();
</script>
</body>
